const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');

const htmlPath = path.join(__dirname, 'index.html');
const htmlContent = fs.readFileSync(htmlPath, 'utf-8');
const dom = new JSDOM(htmlContent);
const doc = dom.window.document;

console.log('=== MANUAL ACCESSIBILITY VERIFICATION ===\n');

const checks = [];

// Check 1: Exactly one <main> element
const mains = doc.querySelectorAll('main');
checks.push({
  pass: mains.length === 1,
  name: 'Exactly one <main> element',
  result: `Found: ${mains.length}`
});

// Check 2: One <h1> as first heading in main
const h1s = doc.querySelectorAll('h1');
checks.push({
  pass: h1s.length === 1,
  name: 'One <h1> on page',
  result: `Found: ${h1s.length}`
});

// Check 3: Skip link present
const skipLink = doc.querySelector('a[href="#main-content"]');
checks.push({
  pass: !!skipLink && skipLink.textContent.toLowerCase().includes('skip'),
  name: 'Skip-to-main link present',
  result: skipLink ? 'Yes' : 'No'
});

// Check 4: Fieldsets have legends
const fieldsets = doc.querySelectorAll('fieldset');
let legendsOk = true;
fieldsets.forEach((fs, idx) => {
  if (!fs.querySelector('legend')) {
    legendsOk = false;
  }
});
checks.push({
  pass: legendsOk && fieldsets.length === 3,
  name: 'All 3 fieldsets have legends',
  result: `${fieldsets.length} fieldsets, all have legends: ${legendsOk}`
});

// Check 5: First question has help text
const q1Fieldset = doc.querySelector('input[name="q1"]').closest('fieldset');
const q1Help = q1Fieldset.querySelector('[id^="q1-help"]');
const q1DescribedBy = q1Fieldset.getAttribute('aria-describedby');
checks.push({
  pass: !!q1Help && q1DescribedBy && q1DescribedBy.includes('q1-help'),
  name: 'Q1 has help text with aria-describedby',
  result: q1Help ? 'Yes' : 'No'
});

// Check 6: All checkboxes have associated labels
const checkboxes = doc.querySelectorAll('input[type="checkbox"]');
let labelsOk = true;
checkboxes.forEach(cb => {
  const id = cb.id;
  const label = doc.querySelector(`label[for="${id}"]`);
  if (!label) {
    labelsOk = false;
  }
});
checks.push({
  pass: labelsOk,
  name: 'All checkboxes have associated labels',
  result: `${checkboxes.length} checkboxes checked`
});

// Check 7: Form has submit button
const submitBtn = doc.querySelector('button[type="submit"]');
checks.push({
  pass: !!submitBtn && submitBtn.textContent.toLowerCase().includes('submit'),
  name: 'Submit button present',
  result: submitBtn ? `"${submitBtn.textContent}"` : 'No'
});

// Check 8: Form wrapped in <form> element
const form = doc.querySelector('form');
checks.push({
  pass: !!form,
  name: 'Content wrapped in <form>',
  result: form ? 'Yes' : 'No'
});

// Check 9: Result message has aria-live
const resultMsg = doc.getElementById('result-message');
checks.push({
  pass: !!resultMsg && resultMsg.getAttribute('aria-live') === 'polite',
  name: 'Result message has aria-live="polite"',
  result: resultMsg && resultMsg.getAttribute('aria-live') ? `${resultMsg.getAttribute('aria-live')}` : 'No'
});

// Check 10: Required indicators present
const legends = doc.querySelectorAll('legend');
let requiredMarkersOk = true;
legends.forEach(legend => {
  if (!legend.querySelector('[aria-hidden="true"]')) {
    requiredMarkersOk = false;
  }
});
checks.push({
  pass: requiredMarkersOk,
  name: 'All questions have visible required indicators (*)',
  result: requiredMarkersOk ? 'Yes' : 'No'
});

// Check 11: Page has valid title
const title = doc.title;
checks.push({
  pass: title && title.length > 0,
  name: 'Page has <title>',
  result: `"${title}"`
});

// Check 12: Form has novalidate (for custom validation)
checks.push({
  pass: form && form.getAttribute('novalidate') !== null,
  name: 'Form has novalidate for custom validation',
  result: form && form.getAttribute('novalidate') !== null ? 'Yes' : 'No'
});

// Print results
console.log('Best Practices Check Results:\n');
checks.forEach(check => {
  const status = check.pass ? '✓' : '✗';
  console.log(`${status} ${check.name}`);
  console.log(`  ${check.result}\n`);
});

const allPass = checks.every(c => c.pass);
console.log(`\nOverall: ${allPass ? 'PASS' : 'FAIL'}`);
process.exit(allPass ? 0 : 1);
EOF
